#!/bin/bash
# Mode hook: Adaptive UI scaling for Tablet vs Laptop mode
MODE="$1"
SHELL_TOML="$HOME/.config/omarchy/shell.toml"

case "$MODE" in
  tablet)
    cat << 'EOF' > "$SHELL_TOML"
# Auto-generated by surface-tablet-mode for Tablet Mode
[bar]
size-horizontal = 34

[spacing]
scale = 1.15
control-gap = 12
control-padding-x = 12
control-padding-y = 6
control-height = 30

[font]
base-size = 13
EOF
    ;;

  laptop)
    # Remove user override to restore stock compact theme defaults
    rm -f "$SHELL_TOML"
    ;;
esac
